<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>City Skyline Day‑Night Cycle</title>
<style>
  body,html{margin:0;padding:0;background:#000;overflow:hidden;}
  canvas{display:block;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');

    const WIDTH = canvas.width = window.innerWidth;
    const HEIGHT = canvas.height = window.innerHeight;
    const CYCLE = 10000; // 10 seconds in ms

    // ----- sky colours -----
    const DAY = [135,206,235];   // light sky blue
    const NIGHT = [10,10,35];    // dark night blue

    // ----- stars (pre‑generated) -----
    const STAR_COUNT = 150;
    const stars = [];
    for (let i = 0; i < STAR_COUNT; i++) {
        stars.push({
            x: Math.random()*WIDTH,
            y: Math.random()*HEIGHT*0.5,
            r: Math.random()*1.5+0.5
        });
    }

    // ----- buildings -----
    const BUILDINGS = [];
    const buildingCount = 12;
    const buildingGap = 4;
    const buildingWidth = (WIDTH - (buildingCount+1)*buildingGap) / buildingCount;

    for (let i = 0; i < buildingCount; i++) {
        const w = buildingWidth;
        const h = HEIGHT* (0.3 + Math.random()*0.5);
        const x = buildingGap + i*(w+buildingGap);
        const y = HEIGHT - h;
        // compute window grid
        const winW = 12, winH = 16, winGap = 4;
        const cols = Math.floor((w - winGap) / (winW+winGap));
        const rows = Math.floor((h - winGap) / (winH+winGap));
        const windows = [];
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                windows.push({
                    x: x + winGap + c*(winW+winGap),
                    y: y + winGap + r*(winH+winGap),
                    w: winW,
                    h: winH
                });
            }
        }
        BUILDINGS.push({x,y,w,h,windows});
    }

    // linear interpolation helper
    const lerp = (a,b,t)=>a+(b-a)*t;

    function draw(timestamp) {
        const t = timestamp % CYCLE;
        const progress = t / CYCLE;               // 0 → 1 over 10 s
        const skyPhase = Math.cos(progress*2*Math.PI)*0.5+0.5; // 1 = day, 0 = night

        // ---- sky ----
        const r = Math.round(lerp(DAY[0], NIGHT[0], 1-skyPhase));
        const g = Math.round(lerp(DAY[1], NIGHT[1], 1-skyPhase));
        const b = Math.round(lerp(DAY[2], NIGHT[2], 1-skyPhase));
        ctx.fillStyle = `rgb(${r},${g},${b})`;
        ctx.fillRect(0,0,WIDTH,HEIGHT);

        // ---- stars (visible when night) ----
        if (skyPhase < 0.35) {
            ctx.fillStyle = '#fff';
            stars.forEach(s=>{
                ctx.globalAlpha = Math.random()*0.5+0.5;
                ctx.beginPath();
                ctx.arc(s.x,s.y,s.r,0,2*Math.PI);
                ctx.fill();
            });
            ctx.globalAlpha = 1;
        }

        // ---- sun ----
        const sunAngle = Math.PI * (progress*2); // 0 → 2π
        const sunX = WIDTH*0.5 + Math.cos(sunAngle)*WIDTH*0.4;
        const sunY = HEIGHT*0.6 + Math.sin(sunAngle)*HEIGHT*0.3;
        if (skyPhase > 0.2) { // hide when fully night
            const sunRadius = 40;
            const grad = ctx.createRadialGradient(sunX,sunY,0,sunX,sunY,sunRadius);
            grad.addColorStop(0,'rgba(255,255,180,0.9)');
            grad.addColorStop(1,'rgba(255,200,0,0)');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(sunX,sunY,sunRadius,0,2*Math.PI);
            ctx.fill();
        }

        // ---- moon (opposite of sun) ----
        const moonAngle = sunAngle + Math.PI; // opposite side
        const moonX = WIDTH*0.5 + Math.cos(moonAngle)*WIDTH*0.4;
        const moonY = HEIGHT*0.6 + Math.sin(moonAngle)*HEIGHT*0.3;
        if (skyPhase < 0.8) { // hide when full day
            const moonRadius = 30;
            ctx.fillStyle = 'rgba(230,230,250,0.8)';
            ctx.beginPath();
            ctx.arc(moonX,moonY,moonRadius,0,2*Math.PI);
            ctx.fill();
        }

        // ---- buildings ----
        BUILDINGS.forEach(b=>{
            // building silhouette
            ctx.fillStyle = '#222';
            ctx.fillRect(b.x,b.y,b.w,b.h);

            // windows
            b.windows.forEach(w=>{
                const lit = skyPhase < 0.4 && Math.random() < 0.35;
                ctx.fillStyle = lit ? '#ffec8b' : '#111';
                ctx.fillRect(w.x,w.y,w.w,w.h);
            });
        });

        requestAnimationFrame(draw);
    }

    requestAnimationFrame(draw);
})();
</script>
</body>
</html>
```

The script animates a looping 10‑second day/night cycle by interpolating sky colour, moving the sun and moon on opposite arcs, showing stars and randomly lighting building windows at night, all drawn each frame on the canvas.
